import snippetsIndex from "@tscircuit/snippets-ai-docs"

export function getSystemPrompt(opts?: { includeAllDocs?: boolean }): string {
  const { includeAllDocs = false } = opts ?? {}

  // Collect auto-generated docs from @tscircuit/snippets-ai-docs
  let autoGeneratedDocs = ""

  if (includeAllDocs) {
    // Include all available documentation
    for (const [key, content] of Object.entries(snippetsIndex)) {
      autoGeneratedDocs += `\n\n### ${key}\n${content}`
    }
  } else {
    // Include core/essential docs by default
    const coreKeys = [
      "overview",
      "basic-syntax",
      "components",
      "footprints",
      "connections",
      "netlist",
    ]
    for (const key of coreKeys) {
      if (key in snippetsIndex) {
        autoGeneratedDocs += `\n\n### ${key}\n${(snippetsIndex as Record<string, string>)[key]}`
      }
    }
    // Fall back to all docs if none of the core keys exist
    if (!autoGeneratedDocs.trim()) {
      for (const [key, content] of Object.entries(snippetsIndex)) {
        autoGeneratedDocs += `\n\n### ${key}\n${content}`
      }
    }
  }

  return `You are an expert tscircuit developer. tscircuit is a TypeScript/React library for building electronic circuits.

## tscircuit Documentation (Auto-Generated)
${autoGeneratedDocs}

## Important Guidelines
- Always export a default function that returns JSX
- Wrap circuit elements in a <board> component with \`width\` and \`height\` props
- Every component must have a unique \`name\` prop
- Use \`footprint\` prop for PCB components (e.g. "0402", "0603", "sot23")
- Specify values with units: resistance="10kohm", capacitance="100nF", voltage="3.3V"
- Import from "tscircuit": import { ... } from "tscircuit"

## Example
\`\`\`tsx
import { A, B } from "tscircuit"

export default () => (
  <board width="20mm" height="20mm">
    <resistor name="R1" resistance="1kohm" footprint="0402" schX={0} schY={0} />
    <led name="LED1" footprint="0402" schX={2} schY={0} />
    <capacitor name="C1" capacitance="100nF" footprint="0402" schX={4} schY={0} />
  </board>
)
\`\`\`
`
}
